**Store:**
```go
type linkStore struct {
	mu    sync.RWMutex
	links map[string]*Link
}

func newLinkStore() *linkStore {
	return &linkStore{links: make(map[string]*Link)}
}

func (s *linkStore) Add(code, url string) *Link {
	// Caller generates a unique code; we just insert
	s.mu.Lock()
	defer s.mu.Unlock()
	l := &Link{Code: code, URL: url, CreatedAt: time.Now()}
	s.links[code] = l
	return l
}

func (s *linkStore) Get(code string) (*Link, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	l, ok := s.links[code]
	return l, ok
}

func (s *linkStore) RecordClick(code string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, ok := s.links[code]
	if !ok {
		return false
	}
	l.clicks++
	return true
}

func (s *linkStore) Stats(code string) (LinkStats, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	l, ok := s.links[code]
	if !ok {
		return LinkStats{}, false
	}
	return LinkStats{
		Code:      l.Code,
		URL:       l.URL,
		CreatedAt: l.CreatedAt,
		Clicks:    l.clicks,
	}, true
}
```

