**createLinkHandler:**

```go
// createLinkHandler ╨╛╨▒╤А╨░╨▒╨░╤В╤Л╨▓╨░╨╡╤В POST /api/links.
// ╨Ю╨╢╨╕╨┤╨░╨╡╤В JSON-╤В╨╡╨╗╨╛ {"url":"..."} ╨╕ ╨▓╨╛╨╖╨▓╤А╨░╤Й╨░╨╡╤В HTTP 201
// ╤Б JSON-╤В╨╡╨╗╨╛╨╝ {"code":"...","url":"..."}.
// ╨Э╨╡╨▓╨░╨╗╨╕╨┤╨╜╤Л╨╡ ╤В╨╡╨╗╨░ ╨╕ URL тАФ HTTP 400, ╨╝╨╡╤В╨╛╨┤╤Л ╨╛╤В╨╗╨╕╤З╨╜╤Л╨╡ ╨╛╤В POST тАФ HTTP 405.
func (a *app) createLinkHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var body struct {
		URL string `json:"url"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		http.Error(w, "invalid JSON body", http.StatusBadRequest)
		return
	}

	if !isValidTargetURL(body.URL) {
		http.Error(w, "field url is required and must be a valid http(s) URL", http.StatusBadRequest)
		return
	}

	code, err := a.store.Add(body.URL)
	if err != nil {
		http.Error(w, "failed to create link", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	_ = json.NewEncoder(w).Encode(map[string]string{
		"code": code,
		"url":  body.URL,
	})
}

// isValidTargetURL ╨┐╤А╨╛╨▓╨╡╤А╤П╨╡╤В, ╤З╤В╨╛ url ╤П╨▓╨╗╤П╨╡╤В╤Б╤П ╨║╨╛╤А╤А╨╡╨║╤В╨╜╤Л╨╝
// http(s)-╨░╨┤╤А╨╡╤Б╨╛╨╝.
func isValidTargetURL(raw string) bool {
