func TestConcurrentClicks(t *testing.T) {
	srv := newLinksTestServer()
	defer srv.Close()

	code := createTestLink(t, srv, "https://example.com/concurrent")

	const workers = 20
	const perWorker = 25

	var wg sync.WaitGroup
	// errors channel? Simpler: collect errors via mutex-protected slice, or just check status and t.Errorf.
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < perWorker; j++ {
				req, err := http.NewRequest(http.MethodGet, srv.URL+"/"+code, nil)
				if err != nil {
					t.Errorf("NewRequest: %v", err)  // hmm, t.Errorf from a goroutine is OK (unlike Fatal)
					return
				}
				resp, err := noRedirectClient().Do(req)
				if err != nil {
					t.Errorf("GET: %v", err)
					return
				}
				resp.Body.Close()
				if resp.StatusCode != http.StatusFound {
					t.Errorf("status = %d, want %d", resp.StatusCode, http.StatusFound)
				}
			}
		}()
	}
	wg.Wait()

	status, raw, err := doRequest(t, srv, http.MethodGet, "/api/links/"+code+"/stats", "")
	if err != nil {...}
	var st LinkStats
	json.Unmarshal
	if st.Clicks != workers*perWorker {
		t.Fatalf("clicks = %d, want %d", st.Clicks, workers*perWorker)
	}
}
