// randomCode ╨│╨╡╨╜╨╡╤А╨╕╤А╤Г╨╡╤В ╤Б╨╗╤Г╤З╨░╨╣╨╜╤Л╨╣ ╨║╨╛╨┤ ╨╕╨╖ codeLen ╤Б╨╕╨╝╨▓╨╛╨╗╨╛╨▓ base62-╨░╨╗╤Д╨░╨▓╨╕╤В╨░.
// ╨С╨░╨╣╤В╤Л crypto/rand, ╨┤╨░╤О╤Й╨╕╨╡ ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╡ >= 4*len(alphabet), ╨╛╤В╨▒╤А╨░╤Б╤Л╨▓╨░╤О╤В╤Б╤П,
// ╤З╤В╨╛╨▒╤Л ╤А╨░╤Б╨┐╤А╨╡╨┤╨╡╨╗╨╡╨╜╨╕╨╡ ╨┐╨╛ ╤Б╨╕╨╝╨▓╨╛╨╗╨░╨╝ ╨▒╤Л╨╗╨╛ ╤А╨░╨▓╨╜╨╛╨╝╨╡╤А╨╜╤Л╨╝.
func randomCode() (string, error) {
	var chars strings.Builder
	chars.Grow(codeLen)
	var buf [16]byte
	for chars.Len() < codeLen {
		if _, err := rand.Read(buf[:]); err != nil {
			return "", fmt.Errorf("╨│╨╡╨╜╨╡╤А╨░╤Ж╨╕╤П ╤Б╨╗╤Г╤З╨░╨╣╨╜╨╛╨│╨╛ ╨║╨╛╨┤╨░: %w", err)
		}
		for _, b := range buf {
			if chars.Len() >= codeLen {
				break
			}
			if int(b) < 4*len(codeAlphabet) {
				chars.WriteByte(codeAlphabet[b%byte(len(codeAlphabet))])
			}
		}
	}
	return chars.String(), nil
}
