```go
// isValidTargetURL ╨┐╤А╨╛╨▓╨╡╤А╤П╨╡╤В, ╤З╤В╨╛ ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╡ ╤П╨▓╨╗╤П╨╡╤В╤Б╤П ╨║╨╛╤А╤А╨╡╨║╤В╨╜╤Л╨╝
// HTTP/HTTPS-URL ╤Б ╨╜╨╡╨┐╤Г╤Б╤В╤Л╨╝ host.
func isValidTargetURL(raw string) bool {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return false
	}
	u, err := url.Parse(raw)
	if err != nil {
		return false
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return false
	}
	return u.Host != ""
}
```

Note: url.Parse rarely errors (it's lenient). E.g., "not a url" parses without error with empty scheme тЖТ rejected by the scheme check. "https://" тЖТ empty host тЖТ rejected. "ftp://example.com" тЖТ rejected by scheme. Good.

